//! Modules generated by `cargo xtask codegen`; see `xtask/src/x86`.
//!
//! Generated code is tables written as `match`es (one arm per variant, so
//! arms repeat and functions are long) and as arrays indexed by numbers the
//! generator itself assigned, which are in bounds by construction. The
//! decoder state mirrors all of XED's storage, including fields only later
//! API will read.

#![allow(
    clippy::match_same_arms,
    clippy::single_match_else,
    clippy::single_match,
    clippy::too_many_lines,
    clippy::unreadable_literal,
    clippy::indexing_slicing,
    clippy::large_stack_arrays,
    clippy::cast_possible_truncation,
    clippy::unnecessary_cast,
    clippy::wildcard_enum_match_arm,
    clippy::needless_return,
    dead_code
)]

pub mod cpuid;
pub mod dynamic;
pub mod fast;
pub mod flags;
pub mod flow;
pub mod form;
pub mod handlers;
pub mod identify;
pub mod ild;
pub mod mnemonic;
pub mod operand;
pub mod register;
pub mod state;
